import { readFileSync } from 'node:fs';
import vm from 'node:vm';
const src = readFileSync(process.argv[2], 'utf8');
class El { constructor(tag){this.tag=tag;this.children=[];this.listeners={};this.value='';this.disabled=false;this.type='';this._text='';}
  get textContent(){return this.children.length?this.children.map(c=>typeof c==='string'?c:c.textContent).join(''):this._text;}
  set textContent(v){this.children=[];this._text=String(v);}
  append(...n){this.children.push(...n);} replaceChildren(...n){this.children=[...n];}
  addEventListener(t,f){(this.listeners[t]??=[]).push(f);} fire(t,ev={preventDefault(){ev.prevented=true;}}){(this.listeners[t]||[]).forEach(f=>f(ev));return ev;} }
const ids={}; for (const id of ['booking-form','room','title','date','start','end','book','filter-date','show-all','booking-list','error']) ids[id]=new El(id);
const calls=[]; let handler;
const document={getElementById:id=>ids[id],createElement:t=>new El(t)};
const fetch=(url,opts)=>{calls.push([url,opts]);return handler(url,opts);};
const reply=(status,body,bad)=>Promise.resolve({status,json:()=>bad?Promise.reject(new SyntaxError('x')):Promise.resolve(body)});
const tick=()=>new Promise(r=>setImmediate(r));
const dump=()=>JSON.stringify(ids['booking-list'].children.map(li=>li.children.map(c=>typeof c==='string'?c:`[${c.tag}:${c.type}:${c.textContent}]`)));
let bookings=[{id:1,room:'Aurora',title:'<b>x</b>',date:'2026-11-03',start:'09:00',end:'10:00'}];
handler=(url,o)=>{ if(url==='/api/rooms')return reply(200,{rooms:['Aurora','Borealis','Cosmos']}); if(url.startsWith('/api/bookings')&&!o)return reply(200,{bookings}); if(o.method==='POST')return reply(409,{error:'room is already booked from 09:00 to 10:00'}); if(o.method==='DELETE')return reply(204,null,true);};
vm.runInNewContext(src,{document,fetch,JSON,Array,Promise});
console.log('initial calls',calls.map(c=>c[0])); await tick();await tick();
console.log('rooms',ids.room.children.map(o=>o.value+'/'+o.textContent)); console.log('list',dump());
ids.title.value=' T ';ids.room.value='Aurora';ids.date.value='2026-11-03';ids.start.value='09:00';ids.end.value='10:00';
let ev=ids['booking-form'].fire('submit'); console.log('prevented',ev.prevented,'book disabled',ids.book.disabled);
ids['booking-form'].fire('submit'); console.log('posts',calls.filter(c=>c[1]?.method==='POST').length, JSON.stringify(calls.at(-1)[1]));
await tick();await tick(); console.log('error',ids.error.textContent,'book',ids.book.disabled,'title',JSON.stringify(ids.title.value));
const btn=ids['booking-list'].children[0].children[1]; btn.fire('click'); console.log('cancel disabled',btn.disabled, calls.at(-1)); await tick();await tick();await tick();
console.log('error',JSON.stringify(ids.error.textContent),'last call',calls.at(-1)[0]);
bookings=[]; ids['filter-date'].value='2026-11-03'; ids['filter-date'].fire('change'); console.log(calls.at(-1)[0]); await tick();await tick(); console.log('list',dump());
// stale fetch
let resolveA; handler=()=>new Promise(r=>{resolveA=r;}); ids['show-all'].fire('click'); console.log(calls.at(-1)[0], JSON.stringify(ids['filter-date'].value));
const first=resolveA; handler=()=>reply(500,{error:'boom'}); ids['filter-date'].fire('change');
await tick();await tick(); first({status:200,json:()=>Promise.resolve({bookings:[]})}); await tick();await tick(); console.log('error after stale',ids.error.textContent);
handler=()=>Promise.reject(new TypeError('down')); ids['booking-form'].fire('submit'); await tick();await tick(); console.log('nores',ids.error.textContent, ids.book.disabled);
handler=()=>reply(400,[1]); ids['booking-form'].fire('submit'); await tick();await tick(); console.log('array body',ids.error.textContent);
EOF
